package com.mentalmadad.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="doctors") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Doctor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="user_id",nullable=false,unique=true) private User user; @Column(nullable=false) private String specialization; @Column(name="license_number",nullable=false,unique=true) private String licenseNumber; @Column(name="years_of_experience",nullable=false) private int yearsOfExperience; @Column(precision=10,scale=2,nullable=false) private BigDecimal consultationFee; @Lob private String about; @Builder.Default @Column(name="available_for_chat") private boolean availableForChat=true; @Builder.Default @Column(name="available_for_video") private boolean availableForVideo=true; @Builder.Default @Column(name="available_in_person") private boolean availableInPerson=false; @Builder.Default private double rating=0.0; @Builder.Default @Column(name="review_count") private int reviewCount=0; @CreationTimestamp @Column(name="created_at",updatable=false) private LocalDateTime createdAt; @UpdateTimestamp @Column(name="updated_at") private LocalDateTime updatedAt; }
